   131→/**
   132→ * Multi-byte ANSEL sequences (combining marks and special combinations)
   133→ * Format: [base_char_hex][combining_byte_hex] => result_character
   134→ * These are combining marks that follow a base character
   135→ */
   136→const ANSEL_COMBINING: Record<string, string> = {
   137→  // Combining acute accent (0xE0)
   138→  "41E0": "\u00C1", // A + acute = Á
   139→  "45E0": "\u00C9", // E + acute = É
