   158→  "65E1": "\u00E8", // e + grave = è
   159→  "69E1": "\u00EC", // i + grave = ì
   160→  "6FE1": "\u00F2", // o + grave = ò
   161→  "75E1": "\u00F9", // u + grave = ù
   162→
   163→  // Combining circumflex (0xE2)
   164→  "41E2": "\u00C2", // A + circumflex = Â
   165→  "45E2": "\u00CA", // E + circumflex = Ê
   166→  "49E2": "\u00CE", // I + circumflex = Î
   167→  "4FE2": "\u00D4", // O + circumflex = Ô
   168→  "55E2": "\u00DB", // U + circumflex = Û
   169→  "61E2": "\u00E2", // a + circumflex = â
   170→  "65E2": "\u00EA", // e + circumflex = ê
   171→  "69E2": "\u00EE", // i + circumflex = î
   172→  "6FE2": "\u00F4", // o + circumflex = ô
   173→  "75E2": "\u00FB", // u + circumflex = û
   174→
   175→  // Combining tilde (0xE3)
   176→  "41E3": "\u00C3", // A + tilde = Ã
   177→  "4EE3": "\u00D1", // N + tilde = Ñ
   178→  "4FE3": "\u00D5", // O + tilde = Õ
