   186→  "41E4": "\u00C4", // A + diaeresis = Ä
   187→  "45E4": "\u00CB", // E + diaeresis = Ë
   188→  "49E4": "\u00CF", // I + diaeresis = Ï
   189→  "4FE4": "\u00D6", // O + diaeresis = Ö
   190→  "55E4": "\u00DC", // U + diaeresis = Ü
