   195→  "75E4": "\u00FC", // u + diaeresis = ü
   196→  "79E4": "\u00FF", // y + diaeresis = ÿ
   197→
   198→  // Combining ring above (0xE5)
   199→  "41E5": "\u00C5", // A + ring = Å
   200→  "61E5": "\u00E5", // a + ring = å
   201→
   202→  // Combining cedilla (0xE8)
   203→  "43E8": "\u00C7", // C + cedilla = Ç
   204→  "63E8": "\u00E7", // c + cedilla = ç
   205→};
   206→
   207→/**
   208→ * Detect GEDCOM file encoding from CHAR tag in HEAD record
   209→ * Returns detected encoding or 'UTF-8' as default
   210→ */
   211→export function detectEncoding(content: string): string {
   212→  // Find HEAD record and CHAR tag
   213→  const lines = content.split(/\r?\n/);
   214→
   215→  for (let i = 0; i < lines.length; i++) {
   216→    const line = lines[i];
   217→    const match = line.match(/^1\s+CHAR\s+(.+)$/);
   218→    if (match) {
   219→      const charset = match[1].trim().toUpperCase();
   220→      // Normalize encoding names
   221→      if (charset.includes("ANSEL")) {
   222→        return "ANSEL";
   223→      }
   224→      if (charset.includes("UTF")) {
   225→        return "UTF-8";
   226→      }
   227→      return charset;
   228→    }
   229→  }
   230→
   231→  // Default to UTF-8
   232→  return "UTF-8";
   233→}
   234→
   235→/**
   236→ * Convert ANSEL encoded bytes to UTF-8 string
   237→ * Handles both single-byte and multi-byte ANSEL sequences
   238→ */
   239→export function anselToUtf8(buffer: Buffer | Uint8Array): string {
   240→  const bytes = buffer instanceof Buffer ? buffer : Buffer.from(buffer);
   241→  const result: string[] = [];
   242→
   243→  let i = 0;
   244→  while (i < bytes.length) {
   245→    const byte = bytes[i];
   246→
   247→    // Handle standard ASCII (0x00-0x7F)
   248→    if (byte < 0x80) {
   249→      result.push(String.fromCharCode(byte));
   250→      i++;
   251→      continue;
   252→    }
   253→
   254→    // Check if current byte is a combining mark (0xE0-0xEF)
   255→    // If so, combine with previous character
   256→    if (byte >= 0xE0 && byte <= 0xEF && result.length > 0) {
   257→      // Remove the last character
   258→      const lastChar = result.pop();
   259→      if (lastChar) {
   260→        // Get the char code of the last character
   261→        const charCode = lastChar.charCodeAt(0);
   262→        const combined = charCode.toString(16).padStart(2, "0").toUpperCase() +
   263→          byte.toString(16).padStart(2, "0").toUpperCase();
   264→
   265→        if (ANSEL_COMBINING[combined]) {
   266→          result.push(ANSEL_COMBINING[combined]);
   267→          i++;
   268→          continue;
   269→        } else {
   270→          // Restore the character and add the combining mark separately
   271→          result.push(lastChar);
   272→          if (ANSEL_TO_UNICODE[byte]) {
   273→            result.push(ANSEL_TO_UNICODE[byte]);
   274→          } else {
   275→            result.push(String.fromCharCode(byte));
   276→          }
   277→          i++;
   278→          continue;
   279→        }
   280→      }
   281→    }
   282→
   283→    // Handle extended character (0x80-0xFF)
   284→    if (ANSEL_TO_UNICODE[byte]) {
   285→      result.push(ANSEL_TO_UNICODE[byte]);
   286→    } else {
   287→      // If not in mapping, try to pass through as-is
   288→      result.push(String.fromCharCode(byte));
   289→    }
   290→    i++;
   291→  }
   292→
   293→  return result.join("");
   294→}
   295→
   296→/**
   297→ * Convert UTF-8 string to ANSEL encoded bytes
   298→ * Returns best-effort conversion; some Unicode characters may not have ANSEL equivalents
   299→ */
   300→export function utf8ToAnsel(text: string): Buffer {
   301→  const bytes: number[] = [];
   302→
   303→  for (const char of text) {
   304→    const code = char.charCodeAt(0);
   305→
   306→    // ASCII range (0x00-0x7F) passes through directly
   307→    if (code < 0x80) {
   308→      bytes.push(code);
   309→      continue;
   310→    }
   311→
   312→    // Find in reverse mapping
   313→    let found = false;
   314→
   315→    // Check single-character mappings first
   316→    for (const [anselCode, unicode] of Object.entries(ANSEL_TO_UNICODE)) {
   317→      if (unicode === char) {
   318→        bytes.push(parseInt(anselCode, 10));
   319→        found = true;
   320→        break;
   321→      }
   322→    }
   323→
   324→    if (found) {
   325→      continue;
   326→    }
   327→
   328→    // Check combining sequences
   329→    for (const [combined, unicode] of Object.entries(ANSEL_COMBINING)) {
   330→      if (unicode === char) {
   331→        const baseByte = parseInt(combined.substring(0, 2), 16);
   332→        const combByte = parseInt(combined.substring(2, 4), 16);
   333→        bytes.push(baseByte, combByte);
   334→        found = true;
   335→        break;
   336→      }
   337→    }
   338→
   339→    if (found) {
   340→      continue;
   341→    }
   342→
   343→    // If not found, use UTF-8 encoding (may not be compatible with ANSEL readers)
   344→    // but better than losing the character
   345→    const utf8Bytes = Buffer.from(char, "utf8");
   346→    bytes.push(...Array.from(utf8Bytes));
   347→  }
   348→
   349→  return Buffer.from(bytes);
   350→}
   351→
   352→/**
   353→ * Re-encode GEDCOM file content from ANSEL to UTF-8 if needed
   354→ * Returns file content with proper encoding
   355→ */
   356→export function normalizeEncoding(content: string): string {
   357→  const encoding = detectEncoding(content);
   358→
   359→  if (encoding === "UTF-8" || encoding === "UTF8") {
   360→    // Already UTF-8, return as-is
   361→    return content;
   362→  }
   363→
   364→  if (encoding === "ANSEL") {
   365→    // Convert from ANSEL to UTF-8
   366→    const bytes = Buffer.from(content, "latin1"); // ANSEL is 8-bit, read as latin1
   367→    const utf8Text = anselToUtf8(bytes);
   368→
   369→    // Update CHAR tag in HEAD to UTF-8
   370→    const lines = utf8Text.split(/\r?\n/);
   371→    const result = lines.map((line) => {
   372→      if (line.match(/^1\s+CHAR\s+ANSEL/)) {
   373→        return "1 CHAR UTF-8";
   374→      }
   375→      return line;
   376→    });
   377→
   378→    return result.join("\n");
   379→  }
   380→
   381→  // Unknown encoding, return as-is
   382→  return content;
   383→}
