   283→   */
   284→  parseDate(gedcomDate: string, version: "5.5.1" | "7.0" = "5.5.1"): string | null {
   285→    if (!gedcomDate || !gedcomDate.trim()) {
   286→      return null;
   287→    }
   288→
   289→    const trimmed = gedcomDate.trim();
   290→
   291→    // Try GEDCOM 7.0 ISO 8601 format first if version is 7.0
   292→    if (version === "7.0") {
   293→      const iso8601Result = this.parseDateISO8601(trimmed);
   294→      if (iso8601Result) {
   295→        return iso8601Result;
   296→      }
   297→    }
   298→
   299→    // Fall back to GEDCOM 5.5.1 format
   300→    const parsed = this.parseDateComponents(trimmed);
   301→
   302→    if (!parsed.year) {
   303→      return null;
   304→    }
   305→
   306→    // Validate day is reasonable
   307→    if (parsed.day && (parsed.day < 1 || parsed.day > 31)) {
   308→      return null;
   309→    }
   310→
   311→    // Build ISO date with available components
   312→    let isoDate = String(parsed.year).padStart(4, "0");
   313→
   314→    if (parsed.month) {
   315→      isoDate += "-" + String(parsed.month).padStart(2, "0");
   316→
   317→      if (parsed.day) {
   318→        isoDate += "-" + String(parsed.day).padStart(2, "0");
   319→      }
   320→    }
   321→
   322→    return isoDate;
   323→  }
   324→
   325→  /**
   326→   * Parse ISO 8601 date format used in GEDCOM 7.0
   327→   * Formats: "1985-01-15", "1985-01", "1985"
   328→   */
   329→  private parseDateISO8601(dateStr: string): string | null {
   330→    // Match ISO 8601 format
   331→    const iso8601Match = dateStr.match(/^(\d{4})(?:-(\d{2})(?:-(\d{2}))?)?$/);
   332→
   333→    if (!iso8601Match) {
   334→      return null;
   335→    }
   336→
   337→    const year = iso8601Match[1];
   338→    const month = iso8601Match[2];
   339→    const day = iso8601Match[3];
   340→
   341→    // Build result
   342→    let result = year;
   343→    if (month) {
   344→      result += "-" + month;
   345→      if (day) {
   346→        result += "-" + day;
   347→      }
   348→    }
   349→
   350→    return result;
   351→  }
   352→
   353→  /**
   354→   * Parse date components from GEDCOM date string
   355→   */
   356→  private parseDateComponents(dateStr: string): ParsedDate {
   357→    const result: ParsedDate = {
   358→      isApproximate: false,
   359→      raw: dateStr,
   360→    };
   361→
   362→    // Check for date qualifiers
   363→    let workingStr = dateStr.trim();
   364→    const qualifierMatch = workingStr.match(/^(ABT|BEF|AFT|BET)\s+/);
   365→    if (qualifierMatch) {
   366→      result.qualifier = qualifierMatch[1] as any;
   367→      result.isApproximate = true;
   368→      workingStr = workingStr.substring(qualifierMatch[0].length).trim();
   369→    }
   370→
   371→    // Handle "BET ... AND ..." format (e.g., "BET 1975 AND 1985" or "BET 1 JAN 1975 AND 1 JAN 1985")
   372→    if (result.qualifier === "BET") {
   373→      // Try full date format first: "BET 15 JAN 1975 AND 15 JAN 1985"
   374→      const betFullMatch = workingStr.match(
   375→        /^(\d{1,2})\s+(\w+)\s+(\d{4})\s+AND\s+(\d{1,2})\s+(\w+)\s+(\d{4})$/
   376→      );
   377→      if (betFullMatch) {
   378→        result.day = parseInt(betFullMatch[1], 10);
   379→        result.month = this.monthToNumber(betFullMatch[2]);
   380→        result.year = parseInt(betFullMatch[3], 10);
   381→        return result;
   382→      }
   383→
   384→      // Try year-only format: "BET 1975 AND 1985"
   385→      const betYearMatch = workingStr.match(/^(\d{4})\s+AND\s+(\d{4})$/);
   386→      if (betYearMatch) {
   387→        result.year = parseInt(betYearMatch[1], 10);
   388→        return result;
   389→      }
   390→    }
   391→
   392→    // Try full date format: "15 JAN 1985"
   393→    const fullMatch = workingStr.match(/^(\d{1,2})\s+(\w+)\s+(\d{4})$/);
   394→    if (fullMatch) {
   395→      result.day = parseInt(fullMatch[1], 10);
   396→      result.month = this.monthToNumber(fullMatch[2]);
   397→      result.year = parseInt(fullMatch[3], 10);
   398→      return result;
   399→    }
   400→
   401→    // Try month-year format: "JAN 1985"
   402→    const monthYearMatch = workingStr.match(/^(\w+)\s+(\d{4})$/);
   403→    if (monthYearMatch) {
   404→      result.month = this.monthToNumber(monthYearMatch[1]);
   405→      result.year = parseInt(monthYearMatch[2], 10);
   406→      return result;
   407→    }
   408→
   409→    // Try year only: "1985"
   410→    const yearMatch = workingStr.match(/^(\d{4})$/);
   411→    if (yearMatch) {
   412→      result.year = parseInt(yearMatch[1], 10);
   413→      return result;
   414→    }
   415→
   416→    return result;
   417→  }
   418→
   419→  /**
   420→   * Convert month name to number (1-12)
   421→   */
   422→  private monthToNumber(monthName: string): number | undefined {
   423→    const months: Record<string, number> = {
   424→      JAN: 1,
   425→      FEB: 2,
   426→      MAR: 3,
   427→      APR: 4,
   428→      MAY: 5,
   429→      JUN: 6,
   430→      JUL: 7,
   431→      AUG: 8,
   432→      SEP: 9,
   433→      SEPT: 9,
   434→      OCT: 10,
   435→      NOV: 11,
   436→      DEC: 12,
   437→    };
   438→    return months[monthName.toUpperCase()];
   439→  }
   440→
   441→  /**
   442→   * Parse name in GEDCOM format
   443→   * Format: "Given /Surname/" or "Given" or "/Surname/"
   444→   */
   445→  parseName(gedcomName: string): { firstName?: string; lastName?: string } {
   446→    if (!gedcomName || !gedcomName.trim()) {
   447→      return {};
   448→    }
   449→
   450→    const trimmed = gedcomName.trim();
   451→
   452→    // Find surname between forward slashes
   453→    const surnameMatch = trimmed.match(/\/([^\/]*)\//);
   454→    const lastName = surnameMatch ? surnameMatch[1].trim() : undefined;
   455→
   456→    // Extract given names (everything before and after surname)
   457→    let firstName: string | undefined;
   458→    if (surnameMatch) {
   459→      // Remove the /surname/ part and trim
   460→      const withoutSurname = trimmed.replace(/\/[^\/]*\//, "").trim();
   461→      firstName = withoutSurname || undefined;
   462→    } else {
   463→      // No surname markers, entire thing is given name
   464→      firstName = trimmed || undefined;
   465→    }
   466→
   467→    return {
   468→      firstName: firstName || undefined,
   469→      lastName: lastName || undefined,
   470→    };
   471→  }
   472→
   473→  /**
   474→   * Validate GEDCOM file structure
   475→   */
   476→  validate(file: GedcomFile): ValidationError[] {
   477→    const errors: ValidationError[] = [];
   478→
   479→    // Check for required records
   480→    if (!file.header) {
   481→      errors.push({
   482→        message: "Missing required HEAD record",
   483→        severity: "error",
   484→      });
   485→    }
   486→
   487→    if (!file.trailer) {
   488→      errors.push({
   489→        message: "Missing required TRLR record",
   490→        severity: "error",
   491→      });
   492→    }
   493→
   494→    // Check for unique xrefs
   495→    const xrefSet = new Set<string>();
   496→    const allRecords = [
   497→      file.header,
   498→      ...file.individuals,
   499→      ...file.families,
   500→      file.trailer,
   501→    ].filter((r): r is GedcomRecord => r !== null && r !== undefined);
   502→
   503→    for (const record of allRecords) {
   504→      if (record.id) {
   505→        if (xrefSet.has(record.id)) {
   506→          errors.push({
   507→            message: `Duplicate xref: ${record.id}`,
   508→            severity: "error",
   509→          });
   510→        }
   511→        xrefSet.add(record.id);
   512→      }
   513→    }
   514→
   515→    // Check for broken references in families
   516→    const personIds = new Set(file.individuals.map((i) => i.id));
   517→    const familyIds = new Set(file.families.map((f) => f.id));
   518→
   519→    for (const family of file.families) {
   520→      const husbandLine = family.tags.get("HUSB")?.[0];
   521→      const wifeLine = family.tags.get("WIFE")?.[0];
   522→      const childLines = family.tags.get("CHIL") || [];
   523→
   524→      if (
   525→        husbandLine?.pointer &&
   526→        !personIds.has(husbandLine.pointer.replace(/@/g, ""))
   527→      ) {
   528→        errors.push({
   529→          message: `Broken reference in family ${family.id}: HUSB ${husbandLine.pointer} not found`,
   530→          severity: "warning",
   531→        });
   532→      }
   533→
   534→      if (
   535→        wifeLine?.pointer &&
   536→        !personIds.has(wifeLine.pointer.replace(/@/g, ""))
   537→      ) {
   538→        errors.push({
   539→          message: `Broken reference in family ${family.id}: WIFE ${wifeLine.pointer} not found`,
   540→          severity: "warning",
   541→        });
   542→      }
   543→
   544→      for (const childLine of childLines) {
   545→        if (
   546→          childLine.pointer &&
   547→          !personIds.has(childLine.pointer.replace(/@/g, ""))
   548→        ) {
   549→          errors.push({
   550→            message: `Broken reference in family ${family.id}: CHIL ${childLine.pointer} not found`,
   551→            severity: "warning",
   552→          });
   553→        }
   554→      }
   555→    }
   556→
   557→    // Check for broken family references in individuals
   558→    for (const person of file.individuals) {
   559→      const famcLines = person.tags.get("FAMC") || [];
   560→      const famsLines = person.tags.get("FAMS") || [];
   561→
   562→      for (const line of famcLines) {
   563→        if (line.pointer && !familyIds.has(line.pointer.replace(/@/g, ""))) {
   564→          errors.push({
   565→            message: `Broken reference in person ${person.id}: FAMC ${line.pointer} not found`,
   566→            severity: "warning",
   567→          });
   568→        }
   569→      }
   570→
   571→      for (const line of famsLines) {
   572→        if (line.pointer && !familyIds.has(line.pointer.replace(/@/g, ""))) {
   573→          errors.push({
   574→            message: `Broken reference in person ${person.id}: FAMS ${line.pointer} not found`,
   575→            severity: "warning",
   576→          });
   577→        }
   578→      }
   579→    }
   580→
   581→    return errors;
   582→  }
   583→
   584→  /**
   585→   * Parse individual record into structured data
   586→   */
   587→  parseIndividual(record: GedcomRecord): ParsedIndividual {
   588→    const id = record.id || "unknown";
   589→
   590→    // Extract names
   591→    const names: Array<{
   592→      full: string;
   593→      firstName?: string;
   594→      lastName?: string;
   595→    }> = [];
   596→    const nameLines = record.tags.get("NAME") || [];
   597→    for (const line of nameLines) {
   598→      const { firstName, lastName } = this.parseName(line.value);
   599→      names.push({
   600→        full: line.value,
   601→        firstName,
   602→        lastName,
   603→      });
   604→    }
   605→
   606→    // Extract sex
   607→    const sexLine = record.tags.get("SEX")?.[0];
   608→    const sex =
   609→      sexLine?.value === "M" || sexLine?.value === "F" || sexLine?.value === "X"
   610→        ? sexLine.value
   611→        : undefined;
   612→
   613→    // Extract birth information
   614→    const birtLine = record.tags.get("BIRT")?.[0];
   615→    const birthDate = birtLine
   616→      ? this.parseDateFromRecord(record, "BIRT")
   617→      : undefined;
   618→    const birthPlace = this.getPlaceFromEvent(record, "BIRT");
   619→
   620→    // Extract death information
   621→    const deathLine = record.tags.get("DEAT")?.[0];
   622→    const deathDate = deathLine
   623→      ? this.parseDateFromRecord(record, "DEAT")
   624→      : undefined;
   625→    const deathPlace = this.getPlaceFromEvent(record, "DEAT");
   626→
   627→    // Extract occupation
   628→    const occuLine = record.tags.get("OCCU")?.[0];
   629→    const occupation = occuLine?.value;
   630→
   631→    // Extract notes (skip empty notes)
   632→    const notes: string[] = [];
   633→    const noteLines = record.tags.get("NOTE") || [];
   634→    for (const line of noteLines) {
   635→      const noteValue = line.value.trim();
   636→      if (noteValue) {
   637→        notes.push(noteValue);
   638→      }
   639→    }
   640→
   641→    // Extract family references
   642→    const familiesAsChild: string[] = [];
   643→    const famcLines = record.tags.get("FAMC") || [];
   644→    for (const line of famcLines) {
   645→      if (line.pointer) {
   646→        familiesAsChild.push(line.pointer.replace(/@/g, ""));
   647→      }
   648→    }
   649→
   650→    const familiesAsSpouse: string[] = [];
   651→    const famsLines = record.tags.get("FAMS") || [];
   652→    for (const line of famsLines) {
   653→      if (line.pointer) {
   654→        familiesAsSpouse.push(line.pointer.replace(/@/g, ""));
   655→      }
   656→    }
   657→
   658→    return {
   659→      id,
   660→      names: names.length > 0 ? names : [{ full: "" }],
   661→      sex,
   662→      birthDate,
   663→      birthPlace,
   664→      deathDate,
   665→      deathPlace,
   666→      occupation,
   667→      notes,
   668→      familiesAsChild,
   669→      familiesAsSpouse,
   670→    };
   671→  }
   672→
   673→  /**
   674→   * Parse family record into structured data
   675→   */
   676→  parseFamily(record: GedcomRecord): ParsedFamily {
   677→    const id = record.id || "unknown";
   678→
   679→    // Extract spouse information
   680→    const husbandLine = record.tags.get("HUSB")?.[0];
   681→    const wifeLine = record.tags.get("WIFE")?.[0];
   682→    const husband = husbandLine?.pointer?.replace(/@/g, "");
   683→    const wife = wifeLine?.pointer?.replace(/@/g, "");
   684→
   685→    // Extract children
   686→    const children: string[] = [];
   687→    const childLines = record.tags.get("CHIL") || [];
   688→    for (const line of childLines) {
   689→      if (line.pointer) {
   690→        children.push(line.pointer.replace(/@/g, ""));
   691→      }
   692→    }
   693→
   694→    // Extract marriage information
   695→    const marriageDate = this.parseDateFromRecord(record, "MARR");
   696→    const marriagePlace = this.getPlaceFromEvent(record, "MARR") || undefined;
   697→
   698→    // Extract divorce information
   699→    const divorceDate = this.parseDateFromRecord(record, "DIV");
   700→
   701→    // Extract notes (skip empty notes)
   702→    const notes: string[] = [];
   703→    const noteLines = record.tags.get("NOTE") || [];
   704→    for (const line of noteLines) {
   705→      const noteValue = line.value.trim();
   706→      if (noteValue) {
   707→        notes.push(noteValue);
   708→      }
   709→    }
   710→
   711→    return {
   712→      id,
   713→      husband,
   714→      wife,
   715→      children,
   716→      marriageDate,
   717→      marriagePlace,
   718→      divorceDate,
   719→      notes,
   720→    };
   721→  }
   722→
   723→  /**
   724→   * Parse date from an event tag (BIRT, DEAT, MARR, etc.)
   725→   */
   726→  private parseDateFromRecord(
   727→    record: GedcomRecord,
   728→    eventTag: string
   729→  ): string | undefined {
   730→    const eventLines = record.tags.get(eventTag) || [];
   731→    for (const eventLine of eventLines) {
   732→      // Look for DATE substructure
   733→      const eventIndex = record.lines.indexOf(eventLine);
   734→
   735→      // Find DATE lines that are children of this event
   736→      for (let i = eventIndex + 1; i < record.lines.length; i++) {
   737→        const line = record.lines[i];
   738→
   739→        // Stop if we reach a line at the same or lower level as the event
   740→        if (line.level <= eventLine.level) {
   741→          break;
   742→        }
   743→
   744→        // Found a DATE child of this event
   745→        if (line.tag === "DATE") {
   746→          const parsed = this.parseDate(line.value, this.gedcomVersion);
   747→          if (parsed) {
   748→            return parsed;
   749→          }
   750→        }
   751→      }
   752→    }
   753→    return undefined;
   754→  }
   755→
   756→  /**
   757→   * Get place from event tag
   758→   */
   759→  private getPlaceFromEvent(
   760→    record: GedcomRecord,
   761→    eventTag: string
   762→  ): string | undefined {
   763→    const eventLines = record.tags.get(eventTag) || [];
   764→    for (const eventLine of eventLines) {
   765→      // Look for PLAC substructure
   766→      const eventIndex = record.lines.indexOf(eventLine);
   767→      for (let i = eventIndex + 1; i < record.lines.length; i++) {
   768→        const line = record.lines[i];
   769→        if (line.level <= eventLine.level) {
   770→          break;
   771→        }
   772→        if (line.tag === "PLAC") {
   773→          return line.value;
   774→        }
   775→      }
   776→    }
   777→    return undefined;
   778→  }
   779→}
