    19→    });
    20→
    21→    it("should detect ANSEL encoding", () => {
    22→      const gedcom = `0 HEAD
    23→1 SOUR Test
    24→1 CHAR ANSEL
    25→1 GEDC
    26→2 VERS 5.5.1
    27→0 TRLR`;
    28→      expect(detectEncoding(gedcom)).toBe("ANSEL");
    29→    });
